public sealed class OverlayFade38 {
 public double Alpha=1;
 public double Step(bool auto,bool near,double seconds){Alpha=auto?Math.Clamp(Alpha+(near?1:-1)*Math.Clamp(seconds,0,.1)/.2,0,1):1;return Alpha;}
}
public sealed class TimelineLayer38:FrameworkElement {
 public MainWindow Host=null!;
 protected override void OnRender(DrawingContext dc){if(Host.Mode!="viewer"||!Host.Config.SlideTimeline)return;var origin=Host.View.TranslatePoint(new Point(),this);dc.PushTransform(new TranslateTransform(origin.X,origin.Y));Host.DrawSlideTimeline38(dc);dc.Pop();}
}
public static class BoardAlignment38 {
 public static Rect[] Arrange(Rect[] sizes,int count,bool rows,double gap){if(sizes.Length==0)return Array.Empty<Rect>();count=Math.Clamp(count,1,sizes.Length);int columns=rows?(int)Math.Ceiling(sizes.Length/(double)count):count;int height=(int)Math.Ceiling(sizes.Length/(double)columns);var widths=new double[columns];var heights=new double[height];for(int i=0;i<sizes.Length;i++){widths[i%columns]=Math.Max(widths[i%columns],sizes[i].Width);heights[i/columns]=Math.Max(heights[i/columns],sizes[i].Height);}var bounds=sizes.Aggregate(Rect.Union);double totalW=widths.Sum()+gap*(columns-1),totalH=heights.Sum()+gap*(height-1);var result=new Rect[sizes.Length];double y=bounds.Y+(bounds.Height-totalH)/2;for(int r=0;r<height;r++){double x=bounds.X+(bounds.Width-totalW)/2;for(int c=0;c<columns;c++){int i=r*columns+c;if(i<sizes.Length)result[i]=new Rect(x+(widths[c]-sizes[i].Width)/2,y+(heights[r]-sizes[i].Height)/2,sizes[i].Width,sizes[i].Height);x+=widths[c]+gap;}y+=heights[r]+gap;}return result;}
}
